    Group = apps.get_model("auth", "Group")

    Venda.objects.update(subtotal=F("total"))
    antigo = Group.objects.filter(name="Coordenador").first()
    if antigo is None:
        return
    gerente, _ = Group.objects.get_or_create(name="Gerente")
